def need(ok, message):
    if not ok:
        raise RuntimeError(message)


def decoded(name):
    item=FILES[name];data=zlib.decompress(base64.b64decode(item['data'],validate=True))
    need(len(data)==item['bytes'] and len(data)<=1024**2 and hashlib.sha256(data).hexdigest()==item['sha256'],'Pinned provider payload differs')
    return data


def launcher(pins):
    return ('''import hashlib,sys
from pathlib import Path
root=Path(__file__).resolve().parent
PINS='''+repr(pins)+'''
for name,pin in PINS.items():
 path=root/name
 if path.resolve(strict=True)!=path or not path.is_file() or hashlib.sha256(path.read_bytes()).hexdigest()!=pin:
  raise RuntimeError('Installed provider source differs: '+name)
sys.path.insert(0,str(root))
from aenv_ub_provider.service import main
raise SystemExit(main())
''').encode()


def stage(directory):
    need(directory.is_absolute() and directory.resolve()==directory and directory.parent.is_dir()
         and not directory.exists() and not directory.is_symlink(),'Use a fresh absolute private installation directory')
    rows={name:decoded(name) for name in FILES}
    need(rows and all(len(Path(name).parts)==2 and Path(name).parts[0] in ('aenv_ub_provider','tests')
                     and Path(name).name.endswith('.py') for name in rows),'Unexpected release layout')
    directory.mkdir(mode=0o777 if os.name=='nt' else 0o700)
    for name,data in rows.items():
        path=directory/name;path.parent.mkdir(mode=0o777 if os.name=='nt' else 0o700,exist_ok=True)
        with path.open('xb') as stream:stream.write(data)
    pins={name:FILES[name]['sha256'] for name in rows if name.startswith('aenv_ub_provider/')}
    with (directory/'provider_entry.py').open('xb') as stream:stream.write(launcher(pins))
    return pins


def main():
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--directory',type=Path)
    parser.add_argument('--install',action='store_true')
    args=parser.parse_args()
    result={'status':'PLAN_ONLY_NO_WRITE_OR_SDK','release':RELEASE,'SDK_called':False,'Guest_created':False,
            'servicesChanged':False,'nativeGuestAccepted':False,'memfilePrivateCowImplemented':False}
    if not args.install:print(json.dumps(result,indent=2));return 0
    need(sys.platform=='linux' and sys.version_info>=(3,11) and os.getuid()==os.geteuid()!=0,'Use ordinary Linux user with Python 3.11+')
    need(args.directory is not None,'Explicit fresh install directory required')
    need(args.directory.parent.resolve(strict=True)==args.directory.parent and args.directory.parent.stat().st_uid==os.geteuid(),'Installation parent is redirected or not owned')
    def interrupted(_signum,_frame):raise KeyboardInterrupt('Installation test interrupted; preserve new source directory')
    signal.signal(signal.SIGTERM,interrupted)
    os.umask(0o077)
    stage(args.directory)
    result.update(directory=str(args.directory),status='PROVIDER_SOURCE_INSTALLED_TESTS_PENDING')
    try:
        with (args.directory/'tests.log').open('xb') as log:
            run=subprocess.run([sys.executable,'-I','-B','-m','unittest','discover','-s',str(args.directory/'tests')],
                               stdout=log,stderr=subprocess.STDOUT,timeout=120)
        result['testsExit']=run.returncode
        need(run.returncode==0,'Provider tests failed; preserve complete log and source')
        result.update(status='NATIVE_RETAINED_PROVIDER_INSTALLED_TESTED_NO_SDK',entry=str(args.directory/'provider_entry.py'))
    except BaseException as error:
        result.update(status='NATIVE_RETAINED_INSTALL_STOPPED_NO_SDK',errorType=type(error).__name__)
        raise
    finally:
        with (args.directory/'installation.json').open('x') as out:json.dump(result,out,indent=2)
        print(json.dumps(result,indent=2))
    return 0


if __name__=='__main__':raise SystemExit(main())
